/* cppi::cf07e9293269a4e4c20cf99bae3faba8beb0384a68bf842014b7b145d73dbe1f */
select  period, count(*) from ma_cost_insights_dev.cost_insights_transaction_detail
where period LIKE '%-F26'  group by period

/* cppi::f0cc67136091b55d58276c632f885d362181840675228e701e35c343a5d48498 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-08' and end_date = '2025-04-08')
and start_date = '2025-04-08' and end_date = '2025-04-08'

/* cppi::481b412dd8d271dfcba7f7fcbb511a41e6c5a2b8c45ca030f77e9d0fefdf9f99 */
SELECT TRIM(currency_code) currency_code, ROUND(spot_rate,5) spot_rate, business_date
FROM market.msci_daily_fx_rates where business_date = date '2025-06-17'

/* cppi::958e9182a1c4430963b768466bb4baf1f6b6d17eaeabd2c85fd40e6a5e9f7561 */
select business_date as date_, security_id, 'SP500_25' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-20' and business_date <= date '2025-06-20' and weight_ndo>0 and id_cppib_index = 'SP500_25_GR_USD_0_0' and security_id is not null

/* cppi::b1247c0061a53dc2ed87e7a5c2c52cb5632cb6d58c0444534e62d660e7b35952 */
select business_date, index_id, currency_code, market_value_base, weight, arrival_time
from (
        select *, max(arrival_time) over (partition by index_id, currency_code, business_date) max_publish
            from performance.production_sa_index_mix_by_currency
            where business_date between date '1989-07-31' and date '2025-01-02'
            and to_date(substring(cast(arrival_time as varchar), 1, 8), 'yyyymmdd') <= date '2025-01-02'
    ) a
where arrival_time = max_publish
